<div class="page-heading"><div><div class="eyebrow">ADMINISTRATION / USERS</div><h1><?= e($title) ?></h1><p><?= isset($editing['id']) ? 'Update profile, role, and sign-in access.' : 'Give a team member access to the workspace.' ?></p></div><a class="button" href="<?= e(url('users')) ?>">Back to users</a></div>
<section class="panel form-panel"><div class="panel-heading"><h2>User details</h2><span class="pill"><?= icon('shield') ?><?= $user['role']==='admin'?'Admin':'Contractor accounts' ?></span></div>
